-- migration_023_new_questions_sept2026i.sql
-- Batch 9 of new questions from "questions to add.pdf" (all Physics & Clinical Measurement):
--   q_sba_hospital_stay_skewed_median_001   (SBA) -- new knowledge box "Types of Data and Statistical Distributions"
--                                                     (+ new images normal-distribution-empirical-rule.svg,
--                                                     skewed-distributions.svg, boxplot-iqr.svg) + relevantReading (Geeky Medics)
--   q_sba_diastolic_bp_empirical_rule_001   (SBA) -- shares the same knowledge box + relevantReading
--
-- New image assets: images/normal-distribution-empirical-rule.svg, images/skewed-distributions.svg,
--   images/boxplot-iqr.svg, images/type1-type2-error-power.svg
-- No new categories (Physics & Clinical Measurement pre-exists).
--
-- Retroactive edits to already-published rows (per explicit PDF instructions), applied via
-- data || jsonb_build_object(...) so only the named fields change and everything else on the
-- row (stem/choices/correct/dateAdded/rotationIndex) is left untouched:
--   q_sba_opioid_renal_copd_fentanyl_001 -- adds relevantReading (2x) to the pre-existing
--                                            "Opioid Metabolism in Renal Impairment" knowledge box
--   q_statistics_001 -- PDF re-submitted this exact MTF (same 5 statements/answers/explanation,
--                        just "The Mann-Whitney U test is used for non-parametric data" instead of
--                        "...is a non-parametric equivalent of the independent samples t-test") as
--                        the base for a new knowledge box on NNT/Type I & II errors/power. Rather
--                        than insert a near-duplicate question, the existing row's explanation gets
--                        the new knowledge box "NNT, Hypothesis Testing and Statistical Power"
--                        appended, plus relevantReading (Geeky Medics). Original wording/answer key
--                        kept unchanged (its phrasing of D is more precise than the PDF's).
--
-- Idempotent for the two inserts (on conflict do nothing); the two updates are NOT idempotent in
-- the sense of re-running twice (a second run would append the knowledge box to q_statistics_001
-- twice) -- run this file once.

-- ===== New questions =====
insert into questions (id, type, data, status) values ('q_sba_hospital_stay_skewed_median_001', 'SBA', '{"dateAdded":"2026-09-18","rotationIndex":120,"question":"Data is collected from 150 patients to assess length of hospital stay following introduction of a robotic procedure. The data is plotted and shows a skewed distribution. Which of the following statements is most accurate?","choices":["The data is continuous","The median value is best used to describe average length of stay","The data is parametric","95% of the data will lie within 2 standard deviations of the mean","The data will be transformed to a normal distribution by plotting the square root of each value"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Length of hospital stay is a classic example of positively (right) skewed data &mdash; most patients have a relatively short stay, but a smaller number with complications or prolonged recovery create a long right tail of high values. For skewed, non-normally distributed data, the median is the appropriate measure of central tendency, as it is resistant to the influence of outliers, unlike the mean, which is pulled in the direction of the skew.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> While length of hospital stay is technically continuous in principle (time-based), in practice it is recorded and analysed in whole days, making it discrete rather than continuous. The stem&rsquo;s description of a skewed distribution is also a clue against continuous, normally-distributed data, which would be expected to show a symmetrical (Gaussian) shape.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> Because the distribution is skewed, the median provides a more representative measure of the &ldquo;typical&rdquo; length of stay than the mean, which would be disproportionately inflated by a small number of patients with unusually long stays.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Parametric statistics assume a normal distribution; skewed data is, by definition, non-parametric in its untransformed form, and should be analysed using non-parametric methods (e.g. median, IQR, Mann-Whitney U) unless successfully transformed to normality.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> The empirical (68-95-99.7) rule applies specifically to normally distributed data &mdash; it does not reliably apply to a skewed distribution, where the relationship between the mean, SD, and data spread is distorted by the skew.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> While transformation techniques (e.g. logarithmic, square root, or reciprocal transformation) can sometimes be applied to skewed data to approximate a normal distribution for parametric analysis, this is not guaranteed for any given dataset, and asserting that a square root transformation specifically will achieve normality is an overstatement.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Types of Data and Statistical Distributions</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"max-width:480px;margin:12px auto 0\"><div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:10px;border:1px solid #EDE3D7\"><iframe src=\"https://www.youtube.com/embed/_Pyi12dn4Kw\" title=\"Video: statistics for medical students\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen loading=\"lazy\"></iframe></div></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">The Normal (Gaussian) Distribution</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The Gaussian (normal) distribution is a continuous, symmetrical, bell-shaped probability distribution defined by two parameters: the <strong>mean (&mu;)</strong>, which fixes the centre of the curve, and the <strong>standard deviation (SD, &sigma;)</strong>, which fixes its spread. In a true normal distribution the mean, median and mode all coincide at the centre. Only continuous quantitative data (e.g. height, weight, blood pressure, plasma drug concentration) can follow a normal distribution &mdash; qualitative data cannot.</p><table style=\"margin:12px 0 0\"><tr><th>Measure</th><th>Definition</th></tr><tr><td><strong>Mean</strong></td><td>The arithmetic average of all values (sum of values &divide; number of values)</td></tr><tr><td><strong>Median</strong></td><td>The middle value when data are ranked in order</td></tr><tr><td><strong>Mode</strong></td><td>The most frequently occurring value</td></tr><tr><td><strong>Standard deviation (SD)</strong></td><td>A measure of how spread out values are around the mean; the square root of the variance</td></tr><tr><td><strong>Variance</strong></td><td>The average of the squared differences from the mean (SD&sup2;)</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/normal-distribution-empirical-rule.svg\" alt=\"The empirical (68-95-99.7) rule for a normal distribution, showing the percentage of data within 1, 2 and 3 standard deviations of the mean\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Skewed (Non-Normal) Distributions</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Non-normally distributed quantitative data is <strong>skewed</strong> &mdash; positively (right) skewed, where a long tail of high values pulls the mean above the median, or negatively (left) skewed, where a long tail of low values pulls the mean below the median. In both cases the mode remains at the peak of the curve, and the median lies between the mean and the mode.</p><div style=\"text-align:center;margin-top:12px\"><img src=\"images/skewed-distributions.svg\" alt=\"Positive skew, symmetrical, and negative skew distributions, showing the relative positions of the mean, median and mode in each\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Spread in Skewed Data: Range and IQR</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">For skewed data the <strong>median</strong> &mdash; not the mean &mdash; is the appropriate measure of central tendency, as it is resistant to outliers. Spread is described using the range and the interquartile range (IQR) rather than SD/variance.</p><table style=\"margin:12px 0 0\"><tr><th>Measure</th><th>Definition</th></tr><tr><td><strong>Range</strong></td><td>The difference between the highest and lowest values in the dataset</td></tr><tr><td><strong>Quartiles (Q1, Q2, Q3)</strong></td><td>The three values that divide ranked data into four equal parts; Q2 is the median</td></tr><tr><td><strong>Interquartile range (IQR)</strong></td><td>Q3 &minus; Q1; the range of the middle 50% of values, unaffected by extreme outliers</td></tr><tr><td><strong>Whiskers</strong></td><td>On a box-and-whisker plot, lines extending to the most extreme values within 1.5&times;IQR of the box; values beyond this are plotted individually as outliers</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/boxplot-iqr.svg\" alt=\"A box-and-whisker plot for a positively skewed distribution, showing the minimum, Q1, median (Q2), Q3, maximum, the interquartile range, and an outlier\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div></div>\n</div></div>","relevantReading":[{"label":"Statistics for medical students","source":"Geeky Medics","url":"https://geekymedics.com/statistics-for-medical-students/"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_diastolic_bp_empirical_rule_001', 'SBA', '{"dateAdded":"2026-09-18","rotationIndex":121,"question":"Data is collected from 300 patients to assess their diastolic blood pressure. The mean diastolic blood pressure is 70mmHg, with a standard deviation of 5mmHg. Which statement best fits this data?","choices":["The highest diastolic pressure in this sample is 85mmHg","The mean value best describes central tendency for a normal distribution","A randomly selected patient from this sample will have a 68% chance of having a diastolic blood pressure between 65mmHg and 75mmHg","95% of the data will lie within 2 standard deviations of the mean","In any randomly selected patient, there will be a 95% chance of their diastolic blood pressure being between 60 and 70mmHg"],"correct":2,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">This question tests correct application of the empirical (68-95-99.7) rule for normally distributed data. With a mean of 70mmHg and an SD of 5mmHg, one SD either side of the mean is 65&ndash;75mmHg, corresponding to approximately 68% of the distribution.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> 85mmHg corresponds to mean + 3 SD (70 + 15), the upper bound of the range containing approximately 99.7% of the data &mdash; not an absolute maximum; values beyond 3 SD remain possible, just increasingly rare.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> This is a true general statement about normal distributions, but it does not apply the specific numerical data given in the question &mdash; it is too generic to be the &ldquo;best fit&rdquo; answer when a more precise, directly calculated statement (C) is available.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Correct.</strong> This is the correctly and precisely applied empirical rule calculation using the actual figures given: 70 &plusmn; 5 = 65&ndash;75mmHg, corresponding to &plusmn;1 SD and therefore ~68% of the distribution.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Also a true general statement about normal distributions, but &mdash; like B &mdash; it does not apply the specific numerical data given, restating the generic rule rather than a calculated figure specific to this sample.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> This describes &ldquo;any randomly selected patient&rdquo; in general rather than one drawn specifically from this sample &mdash; the parameters given (mean 70mmHg, SD 5mmHg) describe this sample&rsquo;s distribution and cannot be generalised to the wider population. The quoted range is also internally inconsistent: 60&ndash;70mmHg spans only mean &minus; 2 SD to the mean itself, a one-sided band, not the symmetrical &plusmn;2 SD (60&ndash;80mmHg) range that a genuine 95% statement would require.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Types of Data and Statistical Distributions</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"max-width:480px;margin:12px auto 0\"><div style=\"position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:10px;border:1px solid #EDE3D7\"><iframe src=\"https://www.youtube.com/embed/_Pyi12dn4Kw\" title=\"Video: statistics for medical students\" style=\"position:absolute;top:0;left:0;width:100%;height:100%;border:0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen loading=\"lazy\"></iframe></div></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">The Normal (Gaussian) Distribution</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The Gaussian (normal) distribution is a continuous, symmetrical, bell-shaped probability distribution defined by two parameters: the <strong>mean (&mu;)</strong>, which fixes the centre of the curve, and the <strong>standard deviation (SD, &sigma;)</strong>, which fixes its spread. In a true normal distribution the mean, median and mode all coincide at the centre. Only continuous quantitative data (e.g. height, weight, blood pressure, plasma drug concentration) can follow a normal distribution &mdash; qualitative data cannot.</p><table style=\"margin:12px 0 0\"><tr><th>Measure</th><th>Definition</th></tr><tr><td><strong>Mean</strong></td><td>The arithmetic average of all values (sum of values &divide; number of values)</td></tr><tr><td><strong>Median</strong></td><td>The middle value when data are ranked in order</td></tr><tr><td><strong>Mode</strong></td><td>The most frequently occurring value</td></tr><tr><td><strong>Standard deviation (SD)</strong></td><td>A measure of how spread out values are around the mean; the square root of the variance</td></tr><tr><td><strong>Variance</strong></td><td>The average of the squared differences from the mean (SD&sup2;)</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/normal-distribution-empirical-rule.svg\" alt=\"The empirical (68-95-99.7) rule for a normal distribution, showing the percentage of data within 1, 2 and 3 standard deviations of the mean\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Skewed (Non-Normal) Distributions</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Non-normally distributed quantitative data is <strong>skewed</strong> &mdash; positively (right) skewed, where a long tail of high values pulls the mean above the median, or negatively (left) skewed, where a long tail of low values pulls the mean below the median. In both cases the mode remains at the peak of the curve, and the median lies between the mean and the mode.</p><div style=\"text-align:center;margin-top:12px\"><img src=\"images/skewed-distributions.svg\" alt=\"Positive skew, symmetrical, and negative skew distributions, showing the relative positions of the mean, median and mode in each\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Spread in Skewed Data: Range and IQR</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">For skewed data the <strong>median</strong> &mdash; not the mean &mdash; is the appropriate measure of central tendency, as it is resistant to outliers. Spread is described using the range and the interquartile range (IQR) rather than SD/variance.</p><table style=\"margin:12px 0 0\"><tr><th>Measure</th><th>Definition</th></tr><tr><td><strong>Range</strong></td><td>The difference between the highest and lowest values in the dataset</td></tr><tr><td><strong>Quartiles (Q1, Q2, Q3)</strong></td><td>The three values that divide ranked data into four equal parts; Q2 is the median</td></tr><tr><td><strong>Interquartile range (IQR)</strong></td><td>Q3 &minus; Q1; the range of the middle 50% of values, unaffected by extreme outliers</td></tr><tr><td><strong>Whiskers</strong></td><td>On a box-and-whisker plot, lines extending to the most extreme values within 1.5&times;IQR of the box; values beyond this are plotted individually as outliers</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/boxplot-iqr.svg\" alt=\"A box-and-whisker plot for a positively skewed distribution, showing the minimum, Q1, median (Q2), Q3, maximum, the interquartile range, and an outlier\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div></div>\n</div></div>","relevantReading":[{"label":"Statistics for medical students","source":"Geeky Medics","url":"https://geekymedics.com/statistics-for-medical-students/"}]}'::jsonb, 'published')
  on conflict (id) do nothing;

